const PRICE_LEVEL_LABELS = ['Günstig −−', 'Günstig −', 'Standard', 'Teuer +', 'Premium ++'];

function setTicketLevel(delta) {
  CLUB.ticketLevel = Math.max(-2, Math.min(2, (CLUB.ticketLevel||0) + delta));
  renderFinancePanel(); syncClubToTeams(); saveGameState();
}
function setSeasonTicketLevel(delta) {
  CLUB.seasonTicketLevel = Math.max(-2, Math.min(2, (CLUB.seasonTicketLevel||0) + delta));
  renderFinancePanel(); saveGameState();
}
function setBannerSlots(delta) {
  const max = bannerSlotsForStadium(CLUB.facilities.stadium);
  const cur = bannerSlotsSold();
  CLUB.bannerSlotsSold = Math.max(0, Math.min(max, cur + delta));
  renderFinancePanel(); saveGameState();
}

// Kasse und Cap (DFL): Gehälter regelt der Salary Cap, nicht ein Gehaltsbudget (D36).
function renderDualBudgetWidget() {
  if (!LEAGUE) return '';
  const K = window.DFLKader;
  const limit = K && K.capLimit ? K.capLimit() : 0, belegt = K && K.capBelegt ? K.capBelegt() : 0;
  const frei = limit - belegt, pct = limit > 0 ? Math.min(100, Math.round(belegt / limit * 100)) : 0;
  const dead = (CLUB.dfl && CLUB.dfl.deadCap) || 0;
  const farbe = pct > 98 ? 'var(--red,#f85149)' : pct > 90 ? 'var(--gold,#d29922)' : 'var(--green,#3fb950)';
  return `
  <div style="display:flex;flex-direction:column;gap:10px;padding:14px;background:var(--bg2,#161b22);border:1px solid var(--border,#30363d);border-radius:10px;margin-bottom:14px">
    <div style="font-size:13px;font-weight:700;color:var(--text,#e6edf3)">Kasse &amp; Cap</div>
    <div style="display:flex;gap:10px;flex-wrap:wrap">
      <div style="flex:1;min-width:160px;padding:10px 12px;background:var(--bg3,#21262d);border-radius:8px;border:1px solid ${CLUB.budget>=0?'var(--border,#30363d)':'var(--red,#f85149)'}">
        <div style="font-size:10px;color:var(--text2,#8b949e);margin-bottom:3px">Kasse</div>
        <div style="font-size:19px;font-weight:700;color:${CLUB.budget>=0?'var(--green,#3fb950)':'var(--red,#f85149)'}">${formatEuro(CLUB.budget)}</div>
        <div style="font-size:9px;color:var(--text3,#6e7681);margin-top:2px">Ausbau · Handgelder · Sponsoren · Zuschauer</div>
      </div>
      <div style="flex:1;min-width:160px;padding:10px 12px;background:var(--bg3,#21262d);border-radius:8px;border:1px solid ${frei<0?'var(--red,#f85149)':'var(--border,#30363d)'}">
        <div style="font-size:10px;color:var(--text2,#8b949e);margin-bottom:3px">Cap frei</div>
        <div style="font-size:19px;font-weight:700;color:${frei<0?'var(--red,#f85149)':'var(--gold,#d29922)'}">${formatEuro(frei)}</div>
        <div style="font-size:9px;color:var(--text3,#6e7681);margin-top:4px">Belegt ${formatEuro(belegt)} von ${formatEuro(limit)}${dead ? ' · Dead Cap ' + formatEuro(dead) : ''}</div>
        <div style="margin-top:6px;height:4px;background:var(--bg4,#30363d);border-radius:2px">
          <div style="height:4px;border-radius:2px;background:${farbe};width:${pct}%;transition:width .3s"></div>
        </div>
      </div>
    </div>
  </div>`;
}
