    const artTxt = e => e.art === 'elfmeter' ? ' <span class="pm-goal-type">Elfmeter</span>' : e.art === 'freistoss' ? ' <span class="pm-goal-type">Freistoß</span>' : '';
    const gegTore = (typeof G !== 'undefined' && Array.isArray(G.gegnerTore)) ? G.gegnerTore : [];
