      if (!p || p.perspektiv) return;
      const n = liste(p).length, anteil = n / meiste, a = p.age || 25;
      const rolle = anteil >= CFG.stamm ? 'stamm' : anteil >= CFG.bank ? 'rotation' : 'bank';
      const pot = p.truePotential || p.ovr;
