    var buf = (typeof CLUB !== 'undefined') ? CLUB._fitnessBuffer : null;
    var bonus = (buf && buf.weeks > 0) ? (buf.recoverBonus || 0) : 0;
    var rec = CFG.recoverPerWeek + (lvl - 1) * 2 + bonus;
