    addEv('info', -1, `Abpfiff (räumliche Engine): ${G.homeGoals}:${G.awayGoals} · Ballbesitz ${sh.possPct}% · ` +
      `Schüsse ${sh.shots}:${sa.shots} · xG ${sh.xg.toFixed(2)}:${sa.xg.toFixed(2)}`, null, tEnde >= 5400 ? `90+${Math.floor(tEnde / 60 - 90) + 1}` : '90');

